and (tdeal.ps in ('T65', 'T66') or tdeal.ps = ipd.ps or ((tdeal.finprod_type2 = 'F02' OR tdeal.finprod_type2 = 'F03') AND tdeal.ps in ('T56', 'T93', 'T94', 'T07', 'T54')))
and (ipd.ps in ('T23', 'T24')
or ((tdeal.finprod_type2 = 'F10') AND tdeal.ps in ('01', '02'))
)
AND tdeal.totle_trade_id = #{tradeId,jdbcType=VARCHAR}

mapper.update:
update TRD_FIN_PRODUCT_DEAL_TOTAL
set IS_CANCEL = #{isCancle,jdbcType=VARCHAR}
WHERE TOTLE_TRADE_ID = #{totalTradeId,jdbcType=VARCHAR}

update TRD_PRODUCT_DEAL
set IS_CANCEL = #{isCancle,jdbcType=VARCHAR},Trade_Status = #{tradeStatus,jdbcType=VARCHAR}
WHERE TRADE_ID =#{trdProductDealList,jdbcType=VARCHAR}

update stl_orders
set order_status = #{tradeStatus,jdbcType=VARCHAR}
WHERE TRADE_ID =#{trdProductDealList,jdbcType=VARCHAR}
